// Normalize direct WF04/WF98 invocation and protected webhook input
// into one plain payload object.

const input = $json ?? {};

const payload =
  input.body !== null &&
  typeof input.body === 'object' &&
  !Array.isArray(input.body)
    ? input.body
    : input;

return {
  json: payload,
};

// Validate the authoritative WF05 invocation contract.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(
      `${fieldName} must be a UUID string`,
    );
  }

  const normalized =
    value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(
      `${fieldName} must be a valid UUID`,
    );
  }

  return normalized;
}

function optionalUuid(value, fieldName) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  return requireUuid(
    value,
    fieldName,
  );
}

const triggerSource = String(
  input.trigger_source ?? '',
)
  .trim()
  .toLowerCase();

if (
  triggerSource !== 'wf04' &&
  triggerSource !== 'wf98'
) {
  throw new Error(
    'trigger_source must be wf04 or wf98',
  );
}

const caseId = requireUuid(
  input.case_id,
  'case_id',
);

const correlationId = requireUuid(
  input.correlation_id,
  'correlation_id',
);

const clientId = optionalUuid(
  input.client_id,
  'client_id',
);

const acceptedSubmissionId = optionalUuid(
  input.accepted_submission_id,
  'accepted_submission_id',
);

const externalOperationId = optionalUuid(
  input.external_operation_id,
  'external_operation_id',
);

if (triggerSource === 'wf04') {
  if (
    clientId === null ||
    acceptedSubmissionId === null
  ) {
    throw new Error(
      'WF04 invocation requires client_id and accepted_submission_id',
    );
  }

  if (externalOperationId !== null) {
    throw new Error(
      'WF04 invocation must not contain external_operation_id',
    );
  }
}

if (triggerSource === 'wf98') {
  if (externalOperationId === null) {
    throw new Error(
      'WF98 invocation requires external_operation_id',
    );
  }

  if (
    clientId !== null ||
    acceptedSubmissionId !== null
  ) {
    throw new Error(
      'WF98 invocation must not contain WF04 identity fields',
    );
  }
}

return {
  json: {
    case_id: caseId,
    correlation_id: correlationId,
    trigger_source: triggerSource,
    client_id: clientId,
    accepted_submission_id:
      acceptedSubmissionId,
    external_operation_id:
      externalOperationId,
  },
};

// Validate WF05 runtime configuration and construct the context
// used by PostgreSQL preparation and the later provider call.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function readInteger(
  name,
  minimum,
  maximum,
) {
  const rawValue = requireText(
    $env[name],
    name,
  );

  const value = Number(rawValue);

  if (
    !Number.isInteger(value) ||
    value < minimum ||
    value > maximum
  ) {
    throw new Error(
      `${name} must be an integer between ${minimum} and ${maximum}`,
    );
  }

  return value;
}

const providerBaseUrl = requireText(
  $env.PROVISIONING_API_BASE_URL,
  'PROVISIONING_API_BASE_URL',
).replace(/\/+$/, '');

let parsedProviderUrl;

try {
  parsedProviderUrl =
    new URL(providerBaseUrl);
} catch {
  throw new Error(
    'PROVISIONING_API_BASE_URL must be a valid URL',
  );
}

if (
  parsedProviderUrl.protocol !== 'http:' &&
  parsedProviderUrl.protocol !== 'https:'
) {
  throw new Error(
    'PROVISIONING_API_BASE_URL must use HTTP or HTTPS',
  );
}

const executionId = requireText(
  $execution.id,
  'execution_id',
);

const leaseSeconds = readInteger(
  'WF05_OPERATION_LEASE_SECONDS',
  1,
  86400,
);

const maxAttempts = readInteger(
  'WF05_OPERATION_MAX_ATTEMPTS',
  1,
  20,
);

let scenario = null;

if (input.trigger_source === 'wf04') {
  scenario = requireText(
    $env.WF05_PROVISIONING_SCENARIO,
    'WF05_PROVISIONING_SCENARIO',
  ).toLowerCase();

  const allowedScenarios =
    new Set([
      'success',
      'retryable_once',
      'retryable_always',
      'terminal',
    ]);

  if (!allowedScenarios.has(scenario)) {
    throw new Error(
      'WF05_PROVISIONING_SCENARIO is invalid',
    );
  }
}

return {
  json: {
    ...input,

    execution_id:
      executionId,

    scenario,

    provider_base_url:
      providerBaseUrl,

    lease_seconds:
      leaseSeconds,

    max_attempts:
      maxAttempts,
  },
};

// Normalize the authoritative PostgreSQL WF05 preparation result
// before routing to provider call, no-op, or WF99 intervention.

const row = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

if (!isPlainObject(row.input_context)) {
  throw new Error(
    'input_context must be a JSON object',
  );
}

if (!isPlainObject(row.preparation_result)) {
  throw new Error(
    'preparation_result must be a JSON object',
  );
}

const inputContext =
  row.input_context;

const result =
  row.preparation_result;

const preparationOutcome = requireText(
  result.preparation_outcome,
  'preparation_outcome',
);

let nextAction;

if (
  preparationOutcome ===
  'ready_to_call'
) {
  nextAction =
    'call_provider';

} else if (
  new Set([
    'already_provisioned',
    'busy',
    'not_due',
    'not_required',
  ]).has(preparationOutcome)
) {
  nextAction =
    'no_action';

} else {
  nextAction =
    'operator_intervention_required';
}

let providerUrl = null;

if (nextAction === 'call_provider') {
  const providerBaseUrl = requireText(
    inputContext.provider_base_url,
    'provider_base_url',
  ).replace(/\/+$/, '');

  const endpointPath = requireText(
    result.endpoint_path,
    'endpoint_path',
  );

  providerUrl =
    providerBaseUrl +
    (
      endpointPath.startsWith('/')
        ? endpointPath
        : `/${endpointPath}`
    );

  requireText(
    result.operation_id,
    'operation_id',
  );

  requireText(
    result.lease_owner,
    'lease_owner',
  );

  requireText(
    result.idempotency_key,
    'idempotency_key',
  );

  requireText(
    result.company_name,
    'company_name',
  );

  requireText(
    result.company_identifier,
    'company_identifier',
  );

  requireText(
    result.scenario,
    'scenario',
  );
}

return {
  json: {
    ...inputContext,
    ...result,

    workflow:
      'WF05',

    next_action:
      nextAction,

    provider_url:
      providerUrl,

    error_code:
      optionalText(result.error_code),
  },
};

// Return a controlled idempotent WF05 no-action result.

const input = $json ?? {};

if (input.next_action !== 'no_action') {
  throw new Error(
    'Return Provisioning No Action Result received an invalid next action',
  );
}

return {
  json: {
    workflow:
      'WF05',

    result:
      'no_action',

    preparation_outcome:
      input.preparation_outcome ?? null,

    operation_claim_outcome:
      input.operation_claim_outcome ?? null,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    operation_id:
      input.operation_id ?? null,

    external_client_id:
      input.external_client_id ?? null,

    case_state:
      input.case_state ?? null,
  },
};

// Build the exact request allowed by the provisioning provider contract.
// Preserve the authoritative WF05 context for the following nodes.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

if (input.next_action !== 'call_provider') {
  throw new Error(
    'Build Provisioning API Request received an invalid next action',
  );
}

const caseId = requireText(
  input.case_id,
  'case_id',
);

const providerUrl = requireText(
  input.provider_url,
  'provider_url',
);

const idempotencyKey = requireText(
  input.idempotency_key,
  'idempotency_key',
);

const companyName = requireText(
  input.company_name,
  'company_name',
);

const companyIdentifier = requireText(
  input.company_identifier,
  'company_identifier',
);

const scenario = requireText(
  input.scenario,
  'scenario',
);

const allowedScenarios = new Set([
  'success',
  'retryable_once',
  'retryable_always',
  'terminal',
]);

if (!allowedScenarios.has(scenario)) {
  throw new Error(
    'scenario is not supported by the provisioning provider',
  );
}

return {
  json: {
    ...input,

    provider_url:
      providerUrl,

    idempotency_key:
      idempotencyKey,

    provider_request_body: {
      caseId,
      companyName,
      companyIdentifier,
      scenario,
    },

    provider_request_started_at:
      new Date().toISOString(),
  },
};

// Normalize every provisioning provider outcome into one WF05 contract.
// The input contains both the authoritative WF05 context and either
// an HTTP response or a transport-level error.

const input = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function optionalText(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

function optionalPositiveInteger(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const parsed = Number(value);

  return (
    Number.isInteger(parsed) &&
    parsed > 0
  )
    ? parsed
    : null;
}

function optionalNonNegativeInteger(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const parsed = Number(value);

  return (
    Number.isInteger(parsed) &&
    parsed >= 0
  )
    ? parsed
    : null;
}

function getHeader(headers, requestedName) {
  if (!isPlainObject(headers)) {
    return null;
  }

  const requested =
    requestedName.toLowerCase();

  for (const [name, value] of Object.entries(headers)) {
    if (name.toLowerCase() === requested) {
      return value;
    }
  }

  return null;
}

const missingContextFields = [
  'case_id',
  'operation_id',
  'lease_owner',
  'company_name',
  'company_identifier',
].filter(
  fieldName =>
    optionalText(input[fieldName]) === null,
);

if (missingContextFields.length > 0) {
  return {
    json: {
      ...input,

      workflow:
        'WF05',

      provider_outcome:
        'invalid_internal_context',

      next_action:
        'operator_intervention_required',

      error_class:
        'workflow_contract_failure',

      error_code:
        'wf05_provider_context_missing',

      error_message:
        `Missing WF05 provider context fields: ${missingContextFields.join(', ')}`,

      retryable:
        false,
    },
  };
}

const statusCode =
  optionalPositiveInteger(
    input.statusCode ??
    input.status_code ??
    input.response?.statusCode,
  );

const responseBody =
  isPlainObject(input.body)
    ? input.body
    : isPlainObject(input.response?.body)
      ? input.response.body
      : {};

const responseHeaders =
  isPlainObject(input.headers)
    ? input.headers
    : isPlainObject(input.response?.headers)
      ? input.response.headers
      : {};

const providerError =
  isPlainObject(responseBody.error)
    ? responseBody.error
    : {};

const transportError =
  isPlainObject(input.error)
    ? input.error
    : {};

const retryAfterSeconds =
  optionalNonNegativeInteger(
    getHeader(
      responseHeaders,
      'retry-after',
    ),
  );

const providerAttemptNumber =
  optionalPositiveInteger(
    responseBody.attemptNumber ??
    providerError.attemptNumber,
  );

const responseReceivedAt =
  new Date().toISOString();

// A transport failure means that no valid HTTP response was received.
if (
  statusCode === null &&
  (
    Object.keys(transportError).length > 0 ||
    optionalText(input.error) !== null ||
    optionalText(input.message) !== null
  )
) {
  return {
    json: {
      ...input,

      workflow:
        'WF05',

      provider_outcome:
        'transport_failure',

      next_action:
        'finalize_retryable_failure',

      http_status:
        null,

      error_class:
        'provider_transport_failure',

      error_code:
        optionalText(
          transportError.code ??
          input.code,
        ) ??
        'PROVISIONING_TRANSPORT_FAILURE',

      error_message:
        optionalText(
          transportError.message ??
          transportError.description ??
          input.message ??
          input.error,
        ) ??
        'The provisioning provider could not be reached.',

      retryable:
        true,

      provider_attempt_number:
        providerAttemptNumber,

      provider_retry_after_seconds:
        retryAfterSeconds,

      provider_response_received_at:
        responseReceivedAt,
    },
  };
}

// Validate HTTP 200 and HTTP 201 as provisioning success responses.
if (
  statusCode === 200 ||
  statusCode === 201
) {
  const externalClientId =
    optionalText(
      responseBody.externalClientId,
    );

  const responseCaseId =
    optionalText(
      responseBody.caseId,
    );

  const responseCompanyName =
    optionalText(
      responseBody.companyName,
    );

  const responseCompanyIdentifier =
    optionalText(
      responseBody.companyIdentifier,
    );

  const providerStatus =
    optionalText(
      responseBody.status,
    );

  const replayed =
    typeof responseBody.replayed === 'boolean'
      ? responseBody.replayed
      : null;

  const successResponseValid =
    externalClientId !== null &&
    responseCaseId === input.case_id &&
    responseCompanyName === input.company_name &&
    responseCompanyIdentifier ===
      input.company_identifier &&
    providerStatus === 'provisioned' &&
    providerAttemptNumber !== null &&
    replayed !== null &&
    (
      (
        statusCode === 200 &&
        replayed === true
      ) ||
      (
        statusCode === 201 &&
        replayed === false
      )
    );

  if (successResponseValid) {
    return {
      json: {
        ...input,

        workflow:
          'WF05',

        provider_outcome:
          'provisioned',

        next_action:
          'finalize_success',

        http_status:
          statusCode,

        external_client_id:
          externalClientId,

        response_case_id:
          responseCaseId,

        response_company_name:
          responseCompanyName,

        response_company_identifier:
          responseCompanyIdentifier,

        provider_status:
          providerStatus,

        provider_attempt_number:
          providerAttemptNumber,

        replayed,

        retryable:
          false,

        provider_response_received_at:
          responseReceivedAt,
      },
    };
  }

  return {
    json: {
      ...input,

      workflow:
        'WF05',

      provider_outcome:
        'invalid_success_response',

      next_action:
        'finalize_terminal_failure',

      http_status:
        statusCode,

      error_class:
        'provider_contract_failure',

      error_code:
        'INVALID_PROVISIONING_SUCCESS_RESPONSE',

      error_message:
        'The provisioning provider returned an invalid success response.',

      retryable:
        false,

      provider_attempt_number:
        providerAttemptNumber,

      provider_retry_after_seconds:
        null,

      provider_response_received_at:
        responseReceivedAt,
    },
  };
}

const providerMarkedRetryable =
  providerError.retryable === true;

const retryableHttpStatus =
  statusCode === 408 ||
  statusCode === 425 ||
  statusCode === 429 ||
  (
    statusCode !== null &&
    statusCode >= 500
  );

const retryable =
  providerMarkedRetryable ||
  retryableHttpStatus;

return {
  json: {
    ...input,

    workflow:
      'WF05',

    provider_outcome:
      retryable
        ? 'retryable_failure'
        : 'terminal_failure',

    next_action:
      retryable
        ? 'finalize_retryable_failure'
        : 'finalize_terminal_failure',

    http_status:
      statusCode,

    error_class:
      retryable
        ? 'provider_temporary_failure'
        : 'provider_terminal_failure',

    error_code:
      optionalText(
        providerError.code,
      ) ??
      (
        retryable
          ? 'PROVISIONING_TEMPORARILY_UNAVAILABLE'
          : 'PROVISIONING_REJECTED'
      ),

    error_message:
      optionalText(
        providerError.message ??
        responseBody.message,
      ) ??
      (
        retryable
          ? 'The provisioning provider returned a temporary failure.'
          : 'The provisioning provider returned a terminal failure.'
      ),

    retryable,

    provider_attempt_number:
      providerAttemptNumber,

    provider_retry_after_seconds:
      retryAfterSeconds,

    provider_response_received_at:
      responseReceivedAt,
  },
};

// Normalize both success and failure PostgreSQL finalization results
// into one routing contract.

const row = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

if (!isPlainObject(row.input_context)) {
  throw new Error(
    'input_context must be a JSON object',
  );
}

if (!isPlainObject(row.finalization_result)) {
  throw new Error(
    'finalization_result must be a JSON object',
  );
}

const inputContext =
  row.input_context;

const result =
  row.finalization_result;

const finalizationOutcome = requireText(
  result.finalization_outcome,
  'finalization_outcome',
);

const caseState =
  optionalText(result.case_state);

const operationStatus =
  optionalText(result.operation_status);

const provisionStepStatus =
  optionalText(result.provision_step_status);

let nextAction;

if (
  finalizationOutcome === 'finalized' ||
  finalizationOutcome === 'already_finalized'
) {
  if (
    caseState === 'provisioned' &&
    operationStatus === 'succeeded' &&
    provisionStepStatus === 'completed'
  ) {
    nextAction =
      'return_success';

  } else if (
    caseState === 'provisioning_failed' &&
    operationStatus === 'failed_retryable' &&
    provisionStepStatus === 'failed_retryable'
  ) {
    nextAction =
      'return_retry_scheduled';

  } else if (
    caseState === 'provisioning_failed' &&
    operationStatus === 'failed_terminal' &&
    provisionStepStatus === 'failed_terminal'
  ) {
    nextAction =
      'operator_intervention_required';

  } else {
    nextAction =
      'operator_intervention_required';
  }

} else {
  nextAction =
    'operator_intervention_required';
}

return {
  json: {
    ...inputContext,
    ...result,

    workflow:
      'WF05',

    finalization_outcome:
      finalizationOutcome,

    next_action:
      nextAction,
  },
};

// Return the verified terminal success result of WF05.

const input = $json ?? {};

if (input.next_action !== 'return_success') {
  throw new Error(
    'Return Provisioning Success Result received an invalid next action',
  );
}

if (
  input.case_state !== 'provisioned' ||
  input.operation_status !== 'succeeded' ||
  input.provision_step_status !== 'completed'
) {
  throw new Error(
    'WF05 success result contains an inconsistent persisted state',
  );
}

const externalClientId =
  String(
    input.external_client_id ?? '',
  ).trim();

if (externalClientId === '') {
  throw new Error(
    'WF05 success result does not contain external_client_id',
  );
}

return {
  json: {
    workflow:
      'WF05',

    result:
      'provisioned',

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    client_id:
      input.client_id ?? null,

    accepted_submission_id:
      input.accepted_submission_id ?? null,

    operation_id:
      input.operation_id ?? null,

    external_client_id:
      externalClientId,

    case_state:
      input.case_state,

    operation_status:
      input.operation_status,

    provision_step_status:
      input.provision_step_status,
  },
};

// Return a controlled WF05 result after a retryable provider failure.

const input = $json ?? {};

if (
  input.next_action !==
  'return_retry_scheduled'
) {
  throw new Error(
    'Return Provisioning Retry Scheduled Result received an invalid next action',
  );
}

if (
  input.case_state !== 'provisioning_failed' ||
  input.operation_status !== 'failed_retryable' ||
  input.provision_step_status !== 'failed_retryable'
) {
  throw new Error(
    'WF05 retry result contains an inconsistent persisted state',
  );
}

const nextRetryAt =
  String(
    input.next_retry_at ?? '',
  ).trim();

if (nextRetryAt === '') {
  throw new Error(
    'WF05 retryable result does not contain next_retry_at',
  );
}

return {
  json: {
    workflow:
      'WF05',

    result:
      'retry_scheduled',

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    operation_id:
      input.operation_id ?? null,

    case_state:
      input.case_state,

    operation_status:
      input.operation_status,

    provision_step_status:
      input.provision_step_status,

    next_retry_at:
      nextRetryAt,
  },
};
